/**
 * SocialDispatchEngine — Dequeues unpublished content packs and publishes
 * them across wired social adapters (LinkedIn, Twitter, Telegram).
 *
 * Tracks which content packs have been dispatched so repeated ticks
 * don't re-publish the same content.
 */

export class SocialDispatchEngine {
  constructor({ store, socialPublishingEngine }) {
    this.store = store;
    this.socialPublishingEngine = socialPublishingEngine;
  }

  /**
   * Find content packs that were generated by the automation engine but
   * have not yet been published to any social channel.
   */
  findUndispatchedContent(campaignId) {
    const packs = this.store.listContentPacks(campaignId);
    return packs.filter(pack => !pack.publishedAt);
  }

  /**
   * Publish all undispatched content for a given campaign.
   * Returns a summary of what was published, skipped, or failed.
   */
  async dispatchCampaign(campaignId, { channels, reason } = {}) {
    const packs = this.findUndispatchedContent(campaignId);
    if (!packs.length) {
      return {
        campaignId,
        dispatched: 0,
        total: 0,
        runs: [],
        summary: { published: 0, failed: 0, skipped: 0 },
      };
    }

    const allRuns = [];

    for (const pack of packs) {
      const variants = pack.variants || [];
      if (!variants.length) {
        // Mark as dispatched even if empty to avoid re-scanning
        pack.publishedAt = new Date().toISOString();
        pack.publishStatus = "no-variants";
        await this.store.addContentPack(pack); // overwrite via persist
        allRuns.push({
          contentPackId: pack.id,
          status: "no-variants",
          published: 0,
        });
        continue;
      }

      const result = await this.socialPublishingEngine.publishVariants({
        campaignId,
        variants,
        channels: channels || ["linkedin", "twitter", "telegram"],
      });

      pack.publishedAt = new Date().toISOString();
      pack.publishStatus = result.summary.published > 0 ? "published" : "failed";
      pack.publishResult = result;

      // Persist pack with publish metadata
      // store.addContentPack is insert-only, so we need to update in-place.
      // Use the store's internal state mutation pattern + persist.
      const idx = this.store.state.contentPacks.findIndex(p => p.id === pack.id);
      if (idx !== -1) {
        this.store.state.contentPacks[idx] = pack;
        await this.store.persist();
        this.store.emitChange("contentPacks", "update", { index: idx, item: pack });
      }

      allRuns.push({
        contentPackId: pack.id,
        status: pack.publishStatus,
        published: result.summary.published,
        failed: result.summary.failed,
        skipped: result.summary.skipped,
        channels: result.runs?.map(r => ({ channel: r.channel, status: r.status })) || [],
      });
    }

    const totals = allRuns.reduce(
      (acc, r) => {
        acc.published += r.published || 0;
        acc.failed += r.failed || 0;
        acc.skipped += r.skipped || 0;
        return acc;
      },
      { published: 0, failed: 0, skipped: 0 },
    );

    return {
      campaignId,
      dispatched: allRuns.filter(r => r.status === "published").length,
      total: packs.length,
      runs: allRuns,
      summary: totals,
    };
  }

  /**
   * Run dispatch for all campaigns that have automation enabled.
   */
  async dispatchAllCampaigns({ channels } = {}) {
    const campaigns = this.store
      .listCampaigns()
      .filter(c => c.automationEnabled);

    const results = [];
    for (const campaign of campaigns) {
      const result = await this.dispatchCampaign(campaign.id, { channels });
      results.push(result);
    }

    return {
      ranAt: new Date().toISOString(),
      campaignsProcessed: results.length,
      totalPublished: results.reduce((s, r) => s + r.summary.published, 0),
      results,
    };
  }
}
